text:
p {
  line-height: 1.8em;
  margin: 0;
}

progress {
  inline-size: 100%;
}

.description {
  line-height: 1.45em;
}

dl {
  display: grid;
  grid-template-columns: [label] max-content [value] minmax(min-content, auto);
  column-gap: 1ch;

  & div {
    display: grid;
    grid-column: 1 / 3;
    grid-template-columns: subgrid;
    grid-template-rows: subgrid;
  }
}

dt {
  font-weight: 600;
  grid-area: label;
}

dd {
  grid-area: value;
  margin: 0;
}

.result-indent {
  grid-column: 2 / 4;
  margin-block: 0;
}
